class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        m = len(grid[0])
        result = []
        index = 0

        for r in range(n):
            if r % 2 == 0:
                cols = range(m)
            else:
                cols = range(m - 1, -1, -1)

            for c in cols:
                if index % 2 == 0:
                    result.append(grid[r][c])
                index += 1

        return result

