class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = defaultdict(int)
        for i in range(n - k + 1):
            for v in set(nums[i:i + k]):
                count[v] += 1
        best = -1
        for v, c in count.items():
            if c == 1 and v > best:
                best = v
        return best

