class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        dist = []
        for ch in s:
            x = ord(ch) - 97
            row = [0] * 26
            for c in range(26):
                d = (c - x) % 26
                row[c] = min(d, 26 - d)
            dist.append(row)

        pair = [[0] * n for _ in range(n)]
        for i in range(n):
            di = dist[i]
            for j in range(i + 1, n):
                dj = dist[j]
                best = 10 ** 9
                for c in range(26):
                    v = di[c] + dj[c]
                    if v < best:
                        best = v
                pair[i][j] = best

        dp = [[None] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        for length in range(2, n + 1):
            for i in range(0, n - length + 1):
                j = i + length - 1
                left = dp[i + 1][j]
                right = dp[i][j - 1]
                m = pair[i][j]
                inner = dp[i + 1][j - 1] if length >= 3 else None
                new = [0] * (k + 1)
                if m <= k:
                    for b in range(k + 1):
                        best = left[b]
                        rb = right[b]
                        if rb > best:
                            best = rb
                        if b >= m:
                            v = 2 + (inner[b - m] if inner is not None else 0)
                            if v > best:
                                best = v
                        new[b] = best
                else:
                    for b in range(k + 1):
                        best = left[b]
                        rb = right[b]
                        if rb > best:
                            best = rb
                        new[b] = best
                dp[i][j] = new

        return dp[0][n - 1][k]

