        foods.append((V, A, C))

    def check(m):
        # DP over calories: dp[c] = list of Pareto-optimal triples (v1, v2, v3), clamped at m
        # Start with empty set
        dp = [[(0, 0, 0)]] + [[] for _ in range(X)]
        for c in range(X + 1):
            if not dp[c]:
                dp[c] = []
        dp = [[(0, 0, 0)] + [()] * 0 for _ in range(X + 1)]
        # Actually simpler: dp[c] is a list of triples
        dp = [[] for _ in range(X + 1)]
        dp[0] = [(0, 0, 0)]
        for (V, A, C) in foods:
            new_dp = [list(dp[c]) for c in range(X + 1)]
            for c in range(X + 1):
                for (a, b, d) in dp[c]:
                    nc = c + C
                    if nc > X:
                        continue
                    if V == 1:
                        a = min(m, a + A)
                    elif V == 2:
                        b = min(m, b + A)
                    else:
                        d = min(m, d + A)
                    new_dp[nc].append((a, b, d))
            # Merge and prune
            for c in range(X + 1):
                triples = new_dp[c]
                # Remove dominated triples: keep only maximal ones
                # Sort by a descending
                triples = list(set(triples))
                triples.sort(key=lambda t: (-t[0], -t[1], -t[2]))
                pruned = []
                for t in triples:
                    a, b, d = t
                    dominated = False
                    for (a2, b2, d2) in pruned:
                        if a2 >= a and b2 >= b and d2 >= d:
                            dominated = True
                            break
                    if not dominated:
                        pruned = [x for x in pruned if not (x[0] <= a and x[1] <= b and x[2] <= d)]
                        pruned.append(t)
                dp[c] = pruned
        # Check if any triple has all >= m
        for c in range(X + 1):
            for (a, b, d) in dp[c]:
                if a >= m and b >= m and d >= m:
                    return True
        return False

    # Binary search
    lo, hi = 0, 0
    for (V, A, C) in foods:
        hi = max(hi, A)
    # Upper bound: total vitamin of any type (but binary search handles it)
    # Actually max possible answer is bounded by max total vitamins of any type
    total = [0, 0, 0]
    for (V, A, C) in foods:
        total[V - 1] += A
    hi = min(total)
    # Binary search
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if check(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

