class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        S = [0] * (n + 1)
        C = [0] * (n + 1)
        for i in range(n):
            S[i + 1] = S[i] + nums[i]
            C[i + 1] = C[i] + cost[i]

        INF = float('inf')
        # f[m][j] = min cost to split first j elements into exactly m subarrays
        f = [[INF] * (n + 1) for _ in range(n + 1)]
        f[0][0] = 0
        # base case: j subarrays, each one element
        for j in range(1, n + 1):
            f[j][j] = f[j - 1][j - 1] + (S[j] + k * j) * cost[j - 1]

        def intersect(s1, a1, s2, a2):
            # x where s1*x + a1 == s2*x + a2
            return (a2 - a1) / (s1 - s2)

        for m in range(1, n + 1):
            hull = []  # list of (slope, intercept), slopes decreasing
            pointer = 0
            for j in range(m, n + 1):
                x = S[j] + k * m
                i = j - 1
                # add line for i (valid only if f[m-1][i] is defined)
                if i >= m - 1 and (m > 1 or i == 0):
                    slope = -C[i]
                    intercept = f[m - 1][i]
                    while len(hull) >= 2:
                        s_a, a_a = hull[-2]
                        s_b, a_b = hull[-1]
                        x_ab = (a_b - a_a) / (s_a - s_b)
                        x_bn = (intercept - a_b) / (s_b - slope)
                        if x_ab >= x_bn:
                            hull.pop()
                        else:
                            break
                    hull.append((slope, intercept))
                # query best line at x
                while pointer + 1 < len(hull):
                    s_p, a_p = hull[pointer]
                    s_n, a_n = hull[pointer + 1]
                    if a_n + s_n * x < a_p + s_p * x:
                        pointer += 1
                    else:
                        break
                s_best, a_best = hull[pointer]
                f[m][j] = (S[j] + k * m) * C[j] + a_best + s_best * x

        ans = min(f[m][n] for m in range(1, n + 1))
        return int(ans)

